mapper.select:
select id, together_id, member_id, together_role, together_guest_member, created_datetime
from tbl_together_member
where together_id = #{togetherId}
  and member_id = #{memberId}

select coalesce(sum(1 + coalesce(together_guest_member, 0)), 0)
from tbl_together_member
where together_id = #{togetherId}

mapper.delete:
delete from tbl_together_member
where together_id = #{togetherId}
  and member_id = #{memberId}
